mapper.select:
/* 1. 프로젝트 일정 */ SELECT EVENT_ID as id, TITLE as title, TO_CHAR(START_DT, 'YYYY-MM-DD') as startDt, TO_CHAR(END_DT + 1, 'YYYY-MM-DD') as endDt, 'PROJ' as itemType, COLOR as color FROM EVENTS WHERE PROJ_ID = #{projId, jdbcType=NUMERIC} AND START_DT BETWEEN TO_DATE(#{startDate}, 'YYYY-MM-DD') AND TO_DATE(#{endDate}, 'YYYY-MM-DD')
UNION ALL /* 2. 워크스페이스 일정 */ SELECT EVENT_ID as id, TITLE as title, TO_CHAR(START_DT, 'YYYY-MM-DD') as startDt, TO_CHAR(END_DT + 1, 'YYYY-MM-DD') as endDt, 'WS' as itemType, COLOR as color FROM EVENTS WHERE WS_ID = #{wsId, jdbcType=NUMERIC} AND EVENT_TYPE = 'WS' AND START_DT BETWEEN TO_DATE(#{startDate}, 'YYYY-MM-DD') AND TO_DATE(#{endDate}, 'YYYY-MM-DD')
UNION ALL /* 3. 공휴일 */ SELECT HLD_ID as id, HLD_NAME as title, TO_CHAR(HLD_DATE, 'YYYY-MM-DD') as startDt, TO_CHAR(HLD_DATE + 1, 'YYYY-MM-DD') as endDt, 'HOLIDAY' as itemType, '#ff0000' as color FROM NATIONAL_HOLIDAYS WHERE HLD_DATE BETWEEN TO_DATE(#{startDate}, 'YYYY-MM-DD') AND TO_DATE(#{endDate}, 'YYYY-MM-DD')

SELECT PROJ_ROLE 
FROM PROJ_MEMBERS 
WHERE PROJ_ID = #{projId} AND USER_ID = #{userId}

mapper.delete:
